metadata.er-schema:
{
  "title": "looply · 类目管理（Collection）实体关系图",
  "version": "v1.1 · 2026-06-04",
  "tables": [
    {
      "name": "collection",
      "comment": "前台商品分组",
      "columns": [
        {
          "name": "fc_id",
          "comment": "分组ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "name_en",
          "comment": "英文名称",
          "constraint": ""
        },
        {
          "name": "url_slug",
          "comment": "URL路径段",
          "constraint": "UNIQUE"
        },
        {
          "name": "icon_url",
          "comment": "入口图URL",
          "constraint": ""
        },
        {
          "name": "banner_url",
          "comment": "Banner图URL",
          "constraint": ""
        },
        {
          "name": "subtitle",
          "comment": "页面副标题",
          "constraint": ""
        },
        {
          "name": "seo_title",
          "comment": "Meta Title",
          "constraint": ""
        },
        {
          "name": "seo_description",
          "comment": "Meta Desc",
          "constraint": ""
        },
        {
          "name": "market_id",
          "comment": "市场（单选）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "channel_id",
          "comment": "渠道（单选）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "source_type",
          "comment": "选品类型 rule/manual",
          "constraint": ""
        },
        {
          "name": "rule_config",
          "comment": "自动选品规则JSON",
          "constraint": ""
        },
        {
          "name": "default_sort_key",
          "comment": "默认排序",
          "constraint": ""
        },
        {
          "name": "visual_filter_enabled",
          "comment": "图文筛模块开关",
          "constraint": ""
        },
        {
          "name": "visual_image_enabled",
          "comment": "图文筛图片模式",
          "constraint": ""
        },
        {
          "name": "quick_filter_enabled",
          "comment": "快筛模块开关",
          "constraint": ""
        },
        {
          "name": "products_per_page",
          "comment": "每页商品数",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态 draft/active/closed",
          "constraint": ""
        },
        {
          "name": "sort_order",
          "comment": "排序权重",
          "constraint": ""
        },
        {
          "name": "is_system",
          "comment": "是否系统级",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "is_system=TRUE 为系统级（All Products），不可删除/下架；价格筛选范围运行时按商品池动态生成，不入库"
    },
    {
      "name": "fc_manual_product",
      "comment": "手动选品关联",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "fc_id",
          "comment": "所属分组",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "listing_id",
          "comment": "商品listingID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "sort_order",
          "comment": "位置（Position）",
          "constraint": ""
        },
        {
          "name": "pinned",
          "comment": "是否固定位置",
          "constraint": ""
        },
        {
          "name": "is_hidden",
          "comment": "是否隐藏",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "添加时间",
          "constraint": ""
        }
      ],
      "note": "UNIQUE(fc_id, listing_id)；商品下架后保留记录，is_hidden 可临时隐藏"
    },
    {
      "name": "fc_hidden_product",
      "comment": "自动选品排除记录",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "fc_id",
          "comment": "所属分组",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "listing_id",
          "comment": "被排除的listingID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "created_at",
          "comment": "排除时间",
          "constraint": ""
        }
      ],
      "note": "UNIQUE(fc_id, listing_id)；自动选品下用于排除单个商品"
    },
    {
      "name": "fc_auto_pin",
      "comment": "自动选品Pin位置",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "fc_id",
          "comment": "所属分组",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "listing_id",
          "comment": "被固定的listingID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "position",
          "comment": "Pin位置",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "固定时间",
          "constraint": ""
        }
      ],
      "note": "UNIQUE(fc_id, listing_id)；自动选品支持Pin，商品下架移出时同步清除pin记录"
    },
    {
      "name": "filter_dimension",
      "comment": "筛选维度（全局池）",
      "columns": [
        {
          "name": "dimension_id",
          "comment": "维度ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "dimension_name_en",
          "comment": "英文名称",
          "constraint": ""
        },
        {
          "name": "source_type",
          "comment": "数据源类型 attribute/brand/series/price/condition/backend_category",
          "constraint": ""
        },
        {
          "name": "source_config",
          "comment": "数据源配置JSON（类目: 勾选节点+展示名）",
          "constraint": ""
        },
        {
          "name": "disp_visual",
          "comment": "图文筛展示样式 card/color",
          "constraint": ""
        },
        {
          "name": "disp_quick",
          "comment": "快筛展示样式 card/panel/slider/color/tree",
          "constraint": ""
        },
        {
          "name": "disp_common",
          "comment": "通用筛展示样式 card/panel/slider/color/tree",
          "constraint": ""
        },
        {
          "name": "value_sort",
          "comment": "枚举值前台展示顺序JSON（取自商品模块，仅排序）",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态 active/inactive",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "source_type=attribute 时经 filter_dimension_source 关联属性；展示样式按图文筛/快筛/通用筛三模块分别配置"
    },
    {
      "name": "filter_dimension_source",
      "comment": "维度-属性多源绑定",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "dimension_id",
          "comment": "所属筛选维度",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "attribute_id",
          "comment": "关联属性定义ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "priority",
          "comment": "多源优先级",
          "constraint": ""
        }
      ],
      "note": "UNIQUE(dimension_id, attribute_id)；仅 source_type=attribute 的维度使用"
    },
    {
      "name": "fc_quick_filter",
      "comment": "快筛项配置",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "fc_id",
          "comment": "所属分组",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "dimension_id",
          "comment": "引用的筛选维度",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "sort_order",
          "comment": "排序",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态 active/inactive",
          "constraint": ""
        }
      ],
      "note": "UNIQUE(fc_id, dimension_id)；快筛每项引用一个筛选维度；模块总开关在 collection.quick_filter_enabled"
    },
    {
      "name": "fc_visual_filter",
      "comment": "图文筛项配置",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "fc_id",
          "comment": "所属分组",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "display_label",
          "comment": "展示文案",
          "constraint": ""
        },
        {
          "name": "image_url",
          "comment": "图片URL（图文模式必填）",
          "constraint": ""
        },
        {
          "name": "condition_config",
          "comment": "筛选项JSON（维度AND·同维度多值OR）",
          "constraint": ""
        },
        {
          "name": "sort_order",
          "comment": "排序",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态 active/inactive",
          "constraint": ""
        }
      ],
      "note": "每项=展示文案+图片+一组筛选项(condition_config)；多个筛选维度间AND、同维度多枚举值OR，不支持OR组合/嵌套；维度引用筛选器池；无系统级All项"
    },
    {
      "name": "fc_sort_config",
      "comment": "Collection排序项配置",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "fc_id",
          "comment": "所属分组",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "sort_key",
          "comment": "排序项key",
          "constraint": ""
        },
        {
          "name": "sort_order",
          "comment": "展示顺序",
          "constraint": ""
        },
        {
          "name": "is_default",
          "comment": "是否默认排序",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态 active/inactive",
          "constraint": ""
        }
      ],
      "note": "UNIQUE(fc_id, sort_key)；决定本 Collection 展示哪些排序项(recommended/newest/price/manual)、顺序及默认项"
    },
    {
      "name": "listing",
      "comment": "商品上架记录",
      "columns": [
        {
          "name": "listing_id",
          "comment": "（商品系统）",
          "constraint": "PRIMARY KEY"
        }
      ],
      "note": "外部引用，字段由商品系统维护，不在本模块展开"
    },
    {
      "name": "attribute_def",
      "comment": "属性定义",
      "columns": [
        {
          "name": "attribute_id",
          "comment": "（商品系统）",
          "constraint": "PRIMARY KEY"
        }
      ],
      "note": "外部引用，字段由商品系统维护，不在本模块展开"
    },
    {
      "name": "brand",
      "comment": "品牌",
      "columns": [
        {
          "name": "brand_id",
          "comment": "（商品系统）",
          "constraint": "PRIMARY KEY"
        }
      ],
      "note": "filter_dimension source_type=brand 时的数据来源（逻辑引用）"
    },
    {
      "name": "series",
      "comment": "系列",
      "columns": [
        {
          "name": "series_id",
          "comment": "（商品系统）",
          "constraint": "PRIMARY KEY"
        }
      ],
      "note": "filter_dimension source_type=series 时的数据来源（逻辑引用）"
    },
    {
      "name": "market",
      "comment": "市场",
      "columns": [
        {
          "name": "market_id",
          "comment": "（商品系统）",
          "constraint": "PRIMARY KEY"
        }
      ],
      "note": "collection.market_id 引用，控制商品池范围（逻辑引用）"
    },
    {
      "name": "channel",
      "comment": "渠道",
      "columns": [
        {
          "name": "channel_id",
          "comment": "（商品系统）",
          "constraint": "PRIMARY KEY"
        }
      ],
      "note": "collection.channel_id 引用，读商品中心渠道管理（逻辑引用）"
    },
    {
      "name": "backend_category",
      "comment": "后台类目",
      "columns": [
        {
          "name": "category_id",
          "comment": "（商品系统）",
          "constraint": "PRIMARY KEY"
        }
      ],
      "note": "既作为 filter_dimension 数据源(source_type=backend_category)，也用于 rule_config 条件字段（均为逻辑引用，非FK）"
    }
  ],
  "relations": [
    {
      "from": "collection",
      "to": "fc_manual_product",
      "type": "1:N",
      "label": "手动选品",
      "color": "#2D72B8",
      "penwidth": 1.8
    },
    {
      "from": "collection",
      "to": "fc_hidden_product",
      "type": "1:N",
