      "color": "#2D72B8",
      "penwidth": 1.4
    },
    {
      "from": "collection",
      "to": "fc_auto_pin",
      "type": "1:N",
      "label": "自动选品Pin",
      "color": "#2D72B8",
      "penwidth": 1.4
    },
    {
      "from": "collection",
      "to": "fc_quick_filter",
      "type": "1:N",
      "label": "快筛配置",
      "color": "#2D72B8",
      "penwidth": 1.4
    },
    {
      "from": "collection",
      "to": "fc_visual_filter",
      "type": "1:N",
      "label": "图文筛配置",
      "color": "#2D72B8",
      "penwidth": 1.4
    },
    {
      "from": "collection",
      "to": "fc_sort_config",
      "type": "1:N",
      "label": "排序配置",
      "color": "#2D72B8",
      "penwidth": 1.4
    },
    {
      "from": "filter_dimension",
      "to": "fc_quick_filter",
      "type": "1:N",
      "label": "被快筛引用",
      "color": "#2E7D4F",
      "penwidth": 1.4
    },
    {
      "from": "filter_dimension",
      "to": "fc_visual_filter",
      "type": "",
      "label": "condition_config 引用\n（JSON，非FK）",
      "color": "#BDBDBD",
      "penwidth": 0.8,
      "style": "dashed"
    },
    {
      "from": "filter_dimension",
      "to": "filter_dimension_source",
      "type": "1:N",
      "label": "多源绑定",
      "color": "#2E7D4F",
      "penwidth": 1.4
    },
    {
      "from": "listing",
      "to": "fc_manual_product",
      "type": "1:N",
      "label": "FK",
      "color": "#9E9E9E",
      "penwidth": 1.0
    },
    {
      "from": "listing",
      "to": "fc_hidden_product",
      "type": "1:N",
      "label": "FK",
      "color": "#9E9E9E",
      "penwidth": 1.0
    },
    {
      "from": "listing",
      "to": "fc_auto_pin",
      "type": "1:N",
      "label": "FK",
      "color": "#9E9E9E",
      "penwidth": 1.0
    },
    {
      "from": "attribute_def",
      "to": "filter_dimension_source",
      "type": "1:N",
      "label": "FK",
      "color": "#9E9E9E",
      "penwidth": 1.0
    },
    {
      "from": "brand",
      "to": "filter_dimension",
      "type": "",
      "label": "source_type=brand",
      "color": "#BDBDBD",
      "penwidth": 0.8,
      "style": "dashed"
    },
    {
      "from": "series",
      "to": "filter_dimension",
      "type": "",
      "label": "source_type=series",
      "color": "#BDBDBD",
      "penwidth": 0.8,
      "style": "dashed"
    },
    {
      "from": "backend_category",
      "to": "filter_dimension",
      "type": "",
      "label": "source_type=backend_category",
      "color": "#BDBDBD",
      "penwidth": 0.8,
      "style": "dashed"
    },
    {
      "from": "backend_category",
      "to": "collection",
      "type": "",
      "label": "rule_config 条件字段\n（JSON引用，非FK）",
      "color": "#BDBDBD",
      "penwidth": 0.8,
      "style": "dashed"
    },
    {
      "from": "market",
      "to": "collection",
      "type": "",
      "label": "market_id",
      "color": "#BDBDBD",
      "penwidth": 0.8,
      "style": "dashed"
    },
    {
      "from": "channel",
      "to": "collection",
      "type": "",
      "label": "channel_id",
      "color": "#BDBDBD",
      "penwidth": 0.8,
      "style": "dashed"
    }
  ],
  "design_rules": {
    "R-01": "Collection 无层级嵌套，扁平结构，导航层级由 Navigation 模块承载",
    "R-02": "商品粒度为 listing 级别，不按 SPU 聚合",
    "R-03": "自动选品/手动选品两种模式互斥（source_type=rule 或 manual）",
    "R-04": "All Products 为系统级 Collection（is_system=TRUE），不可删除、不可下架、rule_config 为空（全量）",
    "R-05": "自动选品支持 Pin（fc_auto_pin）；商品因下架移出 Collection 时同步清除对应 pin 记录",
    "R-06": "手动选品商品下架后 fc_manual_product 记录保留，is_hidden=TRUE，商品重新上架后恢复",
    "R-07": "backend_category 既可作为 filter_dimension 的 source_type，也用于 rule_config 条件字段",
    "R-08": "filter_dimension source_type=attribute 时，通过 filter_dimension_source 支持多个 attribute_def 绑定到同一维度（尺码亦走 attribute）",
    "R-09": "后台商品列表顺序 = 前端实际展示顺序（WYSIWYG），sort_order 字段即最终渲染位置；sort_key=manual（手动排序）即按 fc_manual_product.sort_order / fc_auto_pin.position 的 Pin/拖拽位置展示",
    "R-10": "快筛 chip 商品数为 0、或图文筛绑定的 value 在当前商品池不存在时，前端实时隐藏该项",
    "R-11": "某维度在当前商品池(全集∩图文筛∩搜索词)内有≥2个不同值时才展示，否则前端物理隐藏；count=0 的候选值不返回",
    "R-12": "展示样式 5 种(card/panel/slider/color/tree)，按图文筛/快筛/通用筛三模块分别配置(disp_*)；可选样式=数据源允许∩模块支持。数据源可用样式：brand/series/condition=card/panel，price=slider，backend_category=card/panel/tree，attribute=全部5种",
    "R-13": "展示样式决定前端返回结构：文字卡片/折叠面板=打平列表(类目即末级类目)，树形=父子级树状结构(带children/level)",
    "R-14": "价格筛选范围运行时按各 Collection 商品池动态生成（min=$0，max=最高价向上取整到百位），不入库",
    "R-15": "通用筛选器零配置：按当前商品池从全局维度池(status=active)动态匹配，无 Collection 级配置表",
    "R-16": "筛选联动单向：图文筛缩小商品池→重算快筛/通用筛选器候选项；快筛/通用筛选器不反向影响图文筛",
    "R-17": "快筛与通用筛选器可选项互不影响、互不缩减(避免越筛越少)；但共享同一筛选状态、双向同步选中态；已选保留，仅图文筛切换/新搜索词/用户主动移除时清空"
  }
}
